    //------------------
    let dx = p[3].x-p[0].x;
    let dy = p[3].y-p[0].y;
    let dz = p[3].z-p[0].z;

    let len = (dx*dx + dy*dy + dz*dz);

    let d2pd3 = distancePointsToLine( p[1],p[2],p[0],p[1]);
