function intSphereThickness( r2, ri2, ro, ro2, dir, maxT)
{
  let c = ro2 - r2;
  let c2 = ro2 - ri2;
  let b = ro.dot(dir);
  let t = b*b-c;
  if ( t > 0.0) {
    let st =sqrt(t);
    let t2 = b*b -c2;
    if ( t2 > 0.0)
    {
        let st2 = sqrt(t2 );
        let tmn = -b - st2;
        let tmx = -b + st2;
        let tv= tmn<0. ? tmx : tmn;
        if ( tv> 0. && tv < maxT)
        {

          return  1000000.;
        }
    }
    let t0 = max(-b-st,0.);
    let t1=  max(-b+st,0.);
    t0 = min(t0,maxT);
    t1 = min(t1,maxT);
    return t1 -t0;
  }
  return 0.;
}

class TLTable
{
  let vals;
  numVals = 256;

  constructor()
  {
    vals =new Array(numVals * numVals);
    for (i =0; i < numVals;i++)
      for (j =0; j < numVals; j++)
      {
        let fi  = (float(i)/float(numVals) ) *2.-1.;  // -> i = T.let float fj  = (float(j)/float(numVals) ) *2.-1.;  // ->j = T.L
        // calculate lighting val ( could use shader for this)
        let cosang =cos (abs(acos (fj) - acos (-fi )));
        let spec = max( pow6 (cosang),0.);
        vals[i*numVals + j] = spec;
      }
  }
  GetSpec( TdotV, TdotL )
 {
   // convert into range
   let i = int(( TdotV*127.)+128.);
   let j = int(( TdotL*127.)+128.);
   return vals[ i*numVals + j ];
 } 
}
