   LL.normalize();
  }
  else
  {
    LL.set(L1);
  }
   let ro2 = P.dot(P);
   let v2 = sqrt(v);
     // let over lights, catch highlights as if this was a thin cylinder     
    let TdotV = T.dot(V);

   let shad0 = GetShadow( P, ro2,L, 100000.);
   let shad1 = GetShadow( P, ro2, LL, maxT);//L1);

 /*   let TdotL = T.dot(L);  
