 */  
    let Cspec = shad0 *g_PrecomputeLighting.GetSpec( TdotV, T.dot(L));    
   Cspec += shad1 *g_PrecomputeLighting.GetSpec( TdotV, T.dot(LL))*atten;    
   Cspec *=v;

   let Cdiff =(shad0 +shad1*atten)*v2 ;

  // let multipled by v to make it darker at the roots.  This
 // assumes v=0 at the root, v=1 at the tip.
  let hcolor = lerp(rootcolor, tipcolor, v);
  let Ci = new PVector();
