function ApplyVelocityToCurves( curves, vel,
      stiffness, clen, groundH, 
      pushPoint, viewDir , shaveStength )
{
  let pushRadius = clen+5.;
  vel.mult(stiffness);
  for (let i =0; i < curves.length; i++)
  {
    let cp = curves[i];
    if (!IsVis(cp, viewDir) ) 
       continue;
    // calculate expected end point
    let dir = new PVector();
    dir.set(cp.p[1]);
    dir.sub(cp.p[0]);
    dir.normalize();
    let endpoint = new PVector();
    endpoint.set(dir);
    endpoint.sub(vel);
    // renormalize to keep length
    endpoint.normalize();

    let len = clen * cp.clen;
    cp.p[1].set(dir);
    cp.p[1].mult(len*.25);
    cp.p[1].add(cp.p[0]);

    cp.p[3].set(endpoint);
    cp.p[3].mult(len);
    cp.p[3].add(cp.p[0]);

    cp.p[2].set(endpoint);
    cp.p[2].add(dir);
    cp.p[2].mult(len*.75*.5);
    cp.p[2].add(cp.p[0]);


    // project up to ground
   let xzDir = new PVector();
    xzDir.set(dir);
    xzDir.y=0.;
    xzDir.normalize();

    let ex = min( -(cp.p[2].y-groundH),0.);

    cp.p[2].x -= ex * xzDir.x;
    cp.p[2].z -= ex * xzDir.z;
    cp.p[2].y +=ex;
    ex = min( -(cp.p[3].y-groundH), 0.);
    cp.p[3].x -= ex * xzDir.x;
    cp.p[3].z -= ex * xzDir.z;
    cp.p[3].y +=ex;
     // project away from push point

     let pushDir = new PVector();
     pushDir.set(pushPoint);
     pushDir.sub(cp.p[3]);
     let pd = pushDir.mag();
     let pushamt = min( pd-pushRadius,0);
     pushamt = max( pushamt,-len);
     pushDir.mult(pushamt/pd);
     cp.p[3].add(pushDir);
     cp.p[2].add(pushDir);
     cp.clen *=max(1+(pushamt/pushRadius)*shaveStength,0.);
     if ( cp.clen < 0.01)
     {
       cp.clen = 0.;
     }
  }
}
Curve[] GenerateCurvesOnSphere( amt, rad, 
          aclength, mohawk, face, messy,
         clumpStrength, clumpScale, planeHieght   )
{
  let cps = new Array(amt*amt);

  let cut0 = new PVector(-20,-30,80.);
  let cut1 = new PVector(20,-30,80.);
  let faceCut0 = new PVector(0,20,80.);

  mohawk = 1.-mohawk;
  let cutSize =  28. + face *0.2;
  let faceCutSize = face;
  let faceCutEnd = 1. - face*0.01;
  let cnt = 0;  

  noiseDetail( 3,0.5);
  let amt2 = amt/2;
  for (let i = 0; i < amt; i++)
    for (let j = 0; j < amt2; j++)
    {
      let u = (float(i) + random(0,1))/float(amt);
      let v = (float(j) + random(0,1))/float(amt2);
      // not a good parameterizatin ( too much at the poles       

      // http://mathworld.wolfram.com/SpherePointPicking.html
      let nrm,p;
      if ( planeHieght == 0.)
      {
        let theta = u*2.*PI;
        let phi =acos(2.*v-1.);

        nrm = new PVector( sin(phi)*cos(theta), cos(phi), sin(phi)*sin(theta));
        p = new PVector();
        p.set(nrm);
        p.mult(rad);
      }
      else
      {
        nrm = new PVector( 0., -1., 0.);
        p = new PVector((u*2.-1.)*rad, planeHieght, (v-0.5)*rad);
      }

      // check for invalid areas and cut hair as appropriate
      let cut = 1.;
      cut += min( ( PVector.dist(cut1,p)- cutSize)*.5 ,0);
      cut += min(  (PVector.dist(cut0,p)- cutSize)*.5 ,0);            
      cut += min( (mohawk - abs(nrm.x) ) *4. ,0);
      cut += min( (PVector.dist(faceCut0,p)- faceCutSize)*.5 ,0);
      cut += constrain( (faceCutEnd - nrm.y ) *4. ,-1,0.);

      // tilt normal


      nrm.x += (noise(p.x*clumpScale,p.y*clumpScale,p.z*clumpScale)*2.-1 )*clumpStrength ;
      nrm.y += (noise(p.y*clumpScale,p.z*clumpScale,p.x*clumpScale)*2.-1 )*clumpStrength ;
      nrm.z += (noise(p.z*clumpScale,p.x*clumpScale,p.y*clumpScale)*2.-1 )*clumpStrength ;

      cut = sqrt(cut);
      let ranlen = noise(p.x*8.,p.y*8,p.z*8.)*messy + max(1.-messy,0.);
      ranlen*=cut;

      if ( ranlen < 0.01)  // hair too short
        continue;
      let clength = aclength*ranlen;

      let pts = new Array(4);
      pts[0] = p;

      pts[1] = new PVector();
      pts[1].set(nrm);
      pts[1].mult(clength*.25);
      pts[1].add(p);

      pts[3] = new PVector();
      pts[3].set( nrm);
      pts[3].mult(clength);
      pts[3].add(p);

      pts[2] = new PVector();
      pts[2].set(nrm);
      pts[2].mult(clength*.75);
      pts[2].add(p);

       cps[ cnt] = new Curve( pts,ranlen);
       cnt++;
    }
    let rcps = new Array(cnt);
    for (let i =0; i < rcps.length; i++)
    {
      rcps[i]=cps[i];
    }
   return rcps;
}


