function GuassianSampleSpanFast( inpix, outpix, stride, offset0, offset1, width )
{
  let idx0 = offset0 +2*stride;
  let idx1 = offset1;

  let stride2 = stride*2;
  for (i=2;i<width-2;i+=2)
  {   
    // convert to all integer
