    let g4 = c0 >> 8 & 0xFF;
    let b4 = c0  & 0xFF;
    r4=r4*r4;
    g4=g4*g4;
    b4=b4*b4;

    c0 = inpix[idx0-stride];
    let r1 = c0 >> 16 & 0xFF;
    let g1 = c0 >> 8 & 0xFF;
    let b1 = c0 & 0xFF;
    r1=r1*r1;
    g1=g1*g1;
    b1=b1*b1;
    c0 = inpix[idx0+stride];
    let r2 = c0  >> 16 & 0xFF;
    let g2 = c0  >> 8 & 0xFF;
    let b2 = c0  & 0xFF;
    r2=r2*r2;
    g2=g2*g2;
    b2=b2*b2;

    r2 = (r1+r2)<<2; // *4
    g2 = (g1+g2)<<2;
    b2 = (b1+b2)<<2;

    c0 = inpix[idx0];
    let r3 = c0 >> 16 & 0xFF;
    let g3 = c0 >> 8 & 0xFF;
    let b3 = c0  & 0xFF;
    r3=r3*r3;
    g3=g3*g3;
    b3=b3*b3;
    let r = r0+r4+r2+r3*6;
    let g = g0+g4+g2+g3*6;
    let b = b0+b4+b2+b3*6;

    r = linear_to_gamma[ r >>5]; // /16
    g = linear_to_gamma[g >>5];
    b = linear_to_gamma[b >>5]; 

    let res = (r<<16)|(g<<8)|b;
    outpix[idx1]= res;
    idx1+=stride;
