}
function GuassianSampleSpanFirst( inpix, outpix, stride, stridex, stridex2,
                          offset0, offset1, width, step )
{
  let idx0 = offset0 +2*stride;
  let idx1 = offset1;

  let stride2 = stride*2;

  let c0=inpix[idx0];

  let r0 =  c0 >> 16 & 0xFF;
  let g0 =  c0  >> 8 & 0xFF;
  let b0 =  c0  & 0xFF;
  r0=r0*r0;
  g0=g0*g0;
  b0=b0*b0;

  let r1=r0;let r2=r0;
  let g1=g0;let g2=g0;
  let b1=b0;let b2=b0; 
  for (i=step;i<width-step;i+=step)
  {   
    c0 = inpix[idx0];
    let r3 = c0 >> 16 & 0xFF;
    let g3 = c0 >> 8 & 0xFF;
    let b3 = c0  & 0xFF;
    r3=r3*r3;
    g3=g3*g3;
    b3=b3*b3;

    c0 = inpix[idx0+1];
    let r4 = c0 >> 16 & 0xFF;
    let g4 = c0 >> 8 & 0xFF;
    let b4 = c0 & 0xFF;
    r4=r4*r4;
    g4=g4*g4;
    b4=b4*b4;

    let r = r0+r4+((r1+r3)<<2)+r2*6;
    let g = g0+g4+((g1+g3)<<2)+g2*6;
    let b = b0+b4+((b1+b3)<<2)+b2*6;

     r0=r2;g0=g2;b0=b2;
     r1=r3;g1=g3;b1=b3;
     r2=r4;g2=g4;b2=b4;

    r = linear_to_gamma[ r >>5]; // /16
    g = linear_to_gamma[g >>5];
    b = linear_to_gamma[b >>5]; 
    let res = (r<<16)|(g<<8)|b;
