class GuassianStrip implements WorkItem
{
  let in;
  let out;
  let temp;
  let pass;
  let s;
  let e;

  GuassianStrip( _in, _out, _temp, _pass, _s, _e) {
    pass=_pass;s=_s;e=_e;in=_in;out=_out;temp=_temp;
  }
