  let hopChance = pushPoint.mag()<110. ? 0.2 : 0.01;
  if ( (random(0,1) < hopChance) && g_movement.y ==0.)
      g_movement.Hit(random(20,200));

  if ( tickleAmount > 0.)
    cursor(HAND);
   else
    cursor(CROSS);

  let pdir = new PVector();
  pdir.set(pushPoint);
  pdir.normalize();
  pdir.mult(6.);
  pushPoint.add(pdir);
  g_pushPoint =pushPoint;


  g_movement.Update(time);
  for (let i = 0; i < 7; i++)
    g_gaze[i].update(time+15897*i);

  let groundH = g_movement.y+100.;
  let rotateAmt =0.;
  if ( g_HairAnim)
  {
     let hat = time*.2;
     let hI = floor(hat);
     let hbl = hat - hI;
     hbl = hbl*hbl*(3.-2.*hbl);
     hbl = hbl*hbl*(3.-2.*hbl);
    let hl =PresetHairStyles.length;
    g_HairStyle.Lerp( PresetHairStyles[ int(hI)%hl],  PresetHairStyles[ (int(hI)+1)%hl], hbl);
    GenHair();
    rotateAmt =hat*2.*PI*.5;
  }

  let rot = g_gaze[0].lx*.25+rotateAmt;
  let view = new PVector(sin(rot),0.,-cos(rot));




 if ( g_drawLawn)
{
  for (let i= 0; i < g_Streamer.length;i++)
    g_Streamer[i].update( fireFlyPoint, time, i*125.739);

  } 
 ApplyVelocityToCurves( hairball,new PVector(0.,glastVel -0.96,0.), 
         g_HairStyle.stiffness, g_HairStyle.Length, groundH, pushPoint, view, g_shaveStength );



ss.beginDraw(false);
  noStroke();

  if ( g_drawLawn )
      background(color(0,0,0));
  else
    background(color(196,196,196));


  translate( width/2,  height*9/16);  
  let numSegs = DrawHairBall( time,32., false, g_gaze[0], rotateAmt, g_DrawBabies ? 2 : 1, 
                                tickleAmount, pushPoint);

  // draw babies
  let numBabies = g_DrawBabies ? 6 :0;
  for (let i =0 ; i < numBabies;i++)
  {
    pushMatrix();
    translate( -(i*width)/8 + width/2 - 40 + ((i > 2) ? -140.: 0.), 0);
    scale(0.3);       
    numSegs +=DrawHairBall( time+15897*(i+1),100.,true,  g_gaze[i+1],  
                    rotateAmt, 6, 0., pushPoint);

    popMatrix();
  } 

  if ( g_drawLawn )
  {
   ApplyVelocityToCurves( lawn,new PVector(-0.0,-0.96,0.), 
         g_LawnStyle.stiffness, g_LawnStyle.Length, groundH, pushPoint, view, 0. );

    DrawLawn();

    for (let i= 0; i < g_Streamer.length;i++)
      g_Streamer[i].Draw(view);

    loadPixels();
    DrawLightGlow( fireFlyPoint, 60.,.75);
    for (let i= 0; i < g_Streamer.length;i++)
      g_Streamer[i].DrawGlow();
  //  updatePixels();  
  }

  ss.endDraw();


  g_renderQueue.Wait();  
  //updatePixels();    

  if ( g_drawHelp  )
  {
    textMode(SCREEN); 
    let hairDescription = g_HairStyle.GetDescription();
    text(  "| Fps " + int(frameRate) + "| NumSegs " + numSegs, 20,height-40);
      text(  hairDescription , 20,height-20);
  }
